  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// --- ENUMS (Listas de valores permitidos) ---\nenum TipoGateway {\n  CENTRAL\n  REPETIDOR\n}\n\nenum EstadoDispositivo {\n  ACTIVO\n  INACTIVO\n  MANTENIMIENTO\n}\n\n// --- TABLAS PRINCIPALES ---\n\nmodel Cliente {\n  id               Int               @id @default(autoincrement())\n  nombre           String\n  rut              String?\n  email            String?\n  telefono         String?\n  latitud          Float? // <-- NUEVO\n  longitud         Float? // <-- NUEVO\n  sectores         Sector[]\n  infraestructuras Infraestructura[]\n  gateways         Gateway[]\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n}\n\n// Polígonos estructurales (Caseta, Casa, Centro de Control)\nmodel Infraestructura {\n  id          Int      @id @default(autoincrement())\n  clienteId   Int\n  cliente     Cliente  @relation(fields: [clienteId], references: [id])\n  nombre      String // ej: \"Caseta Central Gateway\"\n  tipo        String // ej: \"CASETA\", \"BODEGA\", \"CASA\"\n  coordenadas Json // Array del polígono\n  color       String?  @default(\"#38bdf8\") // Celeste por defecto\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// Polígonos de plantación\nmodel Sector {\n  id          Int      @id @default(autoincrement())\n  clienteId   Int\n  cliente     Cliente  @relation(fields: [clienteId], references: [id])\n  nombre      String // ej: \"Sector 1\"\n  cultivo     String? // ej: \"Cerezos\", \"Paltos\"\n  coordenadas Json // Array del polígono\n  color       String?  @default(\"#22c55e\") // Verde por defecto\n  nodos       Nodo[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// Topología de Red LoRa\nmodel Gateway {\n  id        String   @id\n  estado    String\n  latitud   Float?\n  longitud  Float?\n  nombre    String?\n  clienteId Int?\n  cliente   Cliente? @relation(fields: [clienteId], references: [id])\n\n  // Agrega esta línea para resolver el error P1012:\n  nodos Nodo[]\n}\n\n// Nodos TinyML en terreno\nmodel Nodo {\n  id        String            @id // ej: \"AGV-011\"\n  sectorId  Int?\n  sector    Sector?           @relation(fields: [sectorId], references: [id])\n  gatewayId String? // Por cuál gateway está ruteando su señal\n  gateway   Gateway?          @relation(fields: [gatewayId], references: [id])\n  latitud   Float?\n  longitud  Float?\n  estado    EstadoDispositivo @default(ACTIVO)\n  bateria   Int?              @default(100)\n  lecturas  Lectura[]\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n}\n\n// El Payload Histórico (Optimizada para IoT)\nmodel Lectura {\n  id     Int    @id @default(autoincrement())\n  nodoId String\n  nodo   Nodo   @relation(fields: [nodoId], references: [id])\n\n  // Variables Críticas (AgroVox)\n  cavitacion Boolean\n  bateria    Int // Porcentaje 0-100\n\n  // Calidad de Red (LoRaWAN)\n  rssi Int? // Potencia de señal en dBm (ej: -115)\n  snr  Float? // Relación señal-ruido\n\n  // Variables Ambientales (Preparado para el futuro)\n  temperatura Float?\n  humedad     Float?\n\n  createdAt DateTime @default(now())\n}\n",
